CREATE TABLE prj24_departments (department_id INTEGER PRIMARY KEY, department_name TEXT NOT NULL UNIQUE);
CREATE TABLE prj24_employees (employee_id INTEGER PRIMARY KEY, employee_code TEXT NOT NULL UNIQUE, department_id INTEGER REFERENCES prj24_departments(department_id));
INSERT INTO prj24_departments VALUES (1, 'Sales');
INSERT INTO prj24_employees VALUES (1, 'E-101', 1), (2, 'E-102', 1);
SELECT d.department_name, COUNT(e.employee_id) AS employee_count FROM prj24_departments d LEFT JOIN prj24_employees e ON e.department_id=d.department_id GROUP BY d.department_id;

